func cmdCloseoutCheck(root string, args []string, stdout, stderr io.Writer) int {
	ref, jsonOutput, ok := parseScopeCheckArgs("closeout-check", args, stderr)
	if !ok {
		return 2
	}
	store, localRef, err := cliReviewStore(root, ref)
	if err != nil {
		render(io.Discard, stderr).Failure("pose closeout-check: " + err.Error())
		return 1
	}
	root, ref = store.Root, localRef
	state, err := cliCloseoutStateForStore(store, ref)
	if err != nil {
		fmt.Fprintf(stderr, "pose closeout-check: %v\n", err)
		return 1
	}
	if jsonOutput {
		if code := writeJSON(stdout, state); code != 0 {
			return code
		}
		if !state.Terminal {
			return 1
		}
		return 0
	}
	fmt.Fprintf(stdout, "closeout.scope=%s\ncloseout.digest=%s\ncloseout.lifecycle_done=%t\ncloseout.review_approved=%t\ncloseout.terminal=%t\ncloseout.next_action=%s\n", state.Scope, state.ScopeDigest, state.LifecycleDone, state.Review.Approved, state.Terminal, state.NextAction)
	if state.Review.Assurance != nil {
		render(stdout, stderr).Field("closeout.review_assurance", posemodel.RenderReviewAssurance(*state.Review.Assurance))
	}
	for _, blocker := range state.Blockers {
		fmt.Fprintf(stderr, "[ERROR] %s\n", blocker)
	}
	if !state.Terminal {
		return 1
	}
	return 0
}

func cliCloseoutState(root, ref string) (posemodel.CloseoutState, error) {
	return cliCloseoutStateIn(root, ref, posemodel.NativeFiles())
